boundaries={'6A93':('specialized_covalent_model','Covalent palmitate needs a specialized model.'),'2REN':('specialized_covalent_model','Covalent NAG glycosylation needs a specialized model.'),'1RNE':('specialized_covalent_model','Covalent NAG glycosylation needs a specialized model.'),'2BEL':('unresolved_input_chemistry','Incomplete CBO plus CCD reference-coordinate stereochemistry conflict; no atom completion or stereoinversion accepted.'),'2ITY':('gap_size_limit','One internal gap is13 residues; the current per-gap limit is12.')}
